from xml.etree import ElementTree as ET
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
ns={'w':W[1:-1]}
t=ET.parse('word/document.xml'); body=t.getroot().find('w:body',ns)
def ptext(p): return ''.join(n.text or '' for n in p.iter(W+'t'))
def style(p):
    st=p.find('w:pPr/w:pStyle',ns); return st.get(W+'val') if st is not None else ''
def walk(el, prefix=''):
    for i,ch in enumerate(el):
        tag=ch.tag.split('}')[1]
        if tag=='p':
            print(f"{prefix}[{i:03d}] <{style(ch)}> {ptext(ch)[:70]}")
        elif tag=='tbl':
            print(f"{prefix}[{i:03d}] <<TABLE {len(ch.findall('w:tr',ns))} rows>>")
            for r,tr in enumerate(ch.findall('w:tr',ns)):
                cells=[' '.join(ptext(p) for p in tc.findall('w:p',ns))[:38] for tc in tr.findall('w:tc',ns)]
                print(f"{prefix}      r{r}: {cells}")
        else:
            print(f"{prefix}[{i:03d}] <<{tag}>>")
walk(body)
EOF

